18	/**
19	 * Maps Owner & OwnerDto using Mapstruct
20	 */
21	@Mapper(uses = PetMapper.class)
22	public interface OwnerMapper {
23	
24	    @Mapping(target = "displayName", source = "owner", qualifiedByName = "formatDisplayName")
25	    @Mapping(target = "initials", source = "owner", qualifiedByName = "formatInitials")
26	    @Mapping(target = "membershipNumber", source = "owner", qualifiedByName = "formatMembershipNumber")
27	    @Mapping(target = "membershipLevel", source = "owner", qualifiedByName = "formatMembershipLevel")
28	    @Mapping(target = "locality", source = "owner", qualifiedByName = "formatLocality")
29	    @Mapping(target = "contactPreference", source = "owner", qualifiedByName = "formatContactPreference")
30	    @Mapping(target = "bulkSignupWarning", ignore = true)
31	    OwnerDto toOwnerDto(Owner owner);
32	
33	    /** Fixed city-to-region table used to derive an owner's {@code locality}. */
34	    java.util.Map<String, String> CITY_REGION = java.util.Map.of(
35	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
36	
37	    /** Region to inclusive 4-digit postcode range {low, high}, used to derive an
38	     *  owner's {@code locality} from its postcode ahead of the city table. */
39	    java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
40	        "NSW", new int[] {2000, 2099},
41	        "VIC", new int[] {3000, 3099},
42	        "QLD", new int[] {4000, 4099});
43	
44	    /**
45	     * Derives an owner's preferred contact channel for the read-only {@code contactPreference}
46	     * field: {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}.
47	     */
48	    @Named("formatContactPreference")
49	    default String formatContactPreference(Owner owner) {
50	        if (owner == null) {
51	            return null;
52	        }
53	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
54	        return hasEmail ? "EMAIL" : "PHONE";
55	    }
56	
57	    /**
58	     * Derives an owner's {@code locality} by preferring the postcode: the region whose
59	     * inclusive 4-digit range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) contains the
60	     * postcode is used first. When the postcode is absent or in no known range, it falls
61	     * back to the fixed city-to-region table (Sydney-&gt;NSW, Melbourne-&gt;VIC,
62	     * Brisbane-&gt;QLD), returning {@code 'UNKNOWN'} when the city is not in the table.
63	     */
64	    @Named("formatLocality")
65	    default String formatLocality(Owner owner) {
66	        if (owner == null) {
67	            return null;
68	        }
69	        String postcode = owner.getPostcode();
70	        if (postcode != null && postcode.matches("^[0-9]{4}$")) {
71	            int value = Integer.parseInt(postcode);
72	            for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
73	                int[] range = entry.getValue();
74	                if (value >= range[0] && value <= range[1]) {
75	                    return entry.getKey();
76	                }
77	            }
78	        }
79	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
80	    }
81	
82	    /**
83	     * Determines an owner's numeric membership level for the read-only {@code membershipLevel}
84	     * field, assigned at creation and ranging from 1 to 3: it starts at 1, gains 1 when an email
85	     * address is present, gains 1 when the owner had no namesakes at creation (namesakeCount is 0),
86	     * and is capped at 3. Level 4 is reserved for tenure.
87	     */
88	    @Named("formatMembershipLevel")
89	    default Integer formatMembershipLevel(Owner owner) {
90	        if (owner == null) {
91	            return null;
92	        }
93	        int level = 1;
94	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
95	        if (hasEmail) {
96	            level++;
97	        }
98	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
99	        if (noNamesakes) {
100	            level++;
101	        }
102	        return Math.min(level, 3);
103	    }
104	
105	    /**
106	     * Formats an owner's membership number as {@code '<customerCode>-M<YY>'}, where YY is the last
107	     * two digits of the registrationDate year (e.g. {@code 'SYD-SMI-0007-M26'}), for the read-only
108	     * {@code membershipNumber} field. Null when the customer code or registration date is absent.
109	     */
110	    @Named("formatMembershipNumber")
111	    default String formatMembershipNumber(Owner owner) {
112	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
113	            return null;
114	        }
115	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
116	    }
117	
118	    /**
119	     * Formats an owner's stored names as {@code 'LastName, FirstName'} for the read-only
120	     * {@code displayName} field.
121	     */
122	    @Named("formatDisplayName")
123	    default String formatDisplayName(Owner owner) {
124	        return owner == null ? null : owner.getLastName() + ", " + owner.getFirstName();
125	    }
126	
127	    /**
128	     * Formats an owner's initials as the upper-cased first letters of firstName and
129	     * lastName, dot-separated with a trailing dot (e.g. {@code 'J.S.'}), for the
130	     * read-only {@code initials} field.
131	     */
132	    @Named("formatInitials")
133	    default String formatInitials(Owner owner) {
134	        return owner == null ? null
135	            : Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
