149	     * text is upper-cased and common street-type abbreviations are expanded (e.g.
150	     * {@code '  12  main  st '} becomes {@code '12 MAIN STREET'}). The required-field rule is
151	     * enforced separately; an address blank after normalization is rejected.
152	     */
153	    @Named("normalizeAddress")
