160	     * {@code '0412 345 678'} becomes {@code '+61412345678'}). The formability rule is
161	     * enforced separately by {@code TelephoneValidation}.
162	     */
163	    @Named("normalizeTelephone")
164	    default String normalizeTelephone(String telephone) {
165	        return TelephoneNormalizer.toE164(telephone);
